1	package main
2	
3	import (
4		"context"
5		"crypto/rand"
6		_ "embed"
7		"encoding/hex"
8		"encoding/json"
9		"errors"
10		"flag"
11		"fmt"
12		"io"
13		"net"
14		"net/http"
15		"os"
16		"os/signal"
17		"path/filepath"
18		"strings"
19		"sync"
20		"syscall"
21		"time"
22	)
23	
24	const product = "ScoreArena"
25	const resourceName = "rooms"
26	
27	//go:embed index.html
28	var indexPage []byte
29	
30	// roomConfig 是创建房间时接受的配置。字段是否缺失在 parseRoomFields 中显式检查，
31	// 不允许把漏填的值悄悄替换为默认值。
32	type roomConfig struct {
33		Name        string `json:"name"`
34		Game        string `json:"game"`
35		Capacity    int    `json:"capacity"`
36		TurnSeconds int    `json:"turnSeconds"`
37	}
38	
39	type room struct {
40		ID          string `json:"id"`
41		Name        string `json:"name"`
42		Game        string `json:"game"`
43		Capacity    int    `json:"capacity"`
44		TurnSeconds int    `json:"turnSeconds"`
45		Status      string `json:"status"`
46		Visibility  string `json:"visibility"`
47		CreatedAt   string `json:"createdAt"`
48	}
49	
50	type roomStore struct {
51		mu   sync.Mutex
52		path string
53	}
54	
55	func newRoomStore(path string) *roomStore {
56		return &roomStore{path: path}
57	}
58	
59	// load 读取数据文件，返回顶层数组中的原始记录以及已占用的房间编号。
60	// 文件无法读取或不是合法数组时返回错误，绝不重置已有数据。
61	// 顶层 JSON 值必须是数组：null、对象、字符串等都不是“没有房间”，
62	// （Go 把顶层 null 解进切片会当成无操作而得到空切片，因此必须先辨别类型）
63	// 只有空数组才表示没有记录。数组中的非对象元素原样保留（兼容历史记录及其附带字段）。
64	func (s *roomStore) load() ([]json.RawMessage, map[string]bool, error) {
65		raw, err := os.ReadFile(s.path)
66		if err != nil {
67			return nil, nil, fmt.Errorf("读取房间数据失败: %w", err)
68		}
69		// 先解出顶层原始值：json.Decoder 会跳过 null 前后的合法 JSON 空白，
70		// 既能精确判断顶层类型，也顺带拒绝尾随多余内容。
71		var top json.RawMessage
72		if err := json.Unmarshal(raw, &top); err != nil {
73			return nil, nil, fmt.Errorf("房间数据不是合法的数组: %w", err)
74		}
75		trimmed := strings.TrimSpace(string(top))
76		if trimmed == "" || trimmed[0] != '[' {
77			return nil, nil, errors.New("房间数据必须是数组，不能是 null 或其他非数组内容")
78		}
79		var records []json.RawMessage
80		if err := json.Unmarshal(top, &records); err != nil {
81			return nil, nil, fmt.Errorf("房间数据不是合法的数组: %w", err)
82		}
83		used := make(map[string]bool, len(records))
84		for _, rec := range records {
85			var probe struct {
86				ID string `json:"id"`
87			}
88			if err := json.Unmarshal(rec, &probe); err == nil && probe.ID != "" {
89				used[probe.ID] = true
90			}
91		}
92		return records, used, nil
93	}
94	
95	// create 校验配置、写入新记录并返回保存后的房间。
96	func (s *roomStore) create(cfg roomConfig) (room, int, error) {
97		if code, msg, ok := validateConfig(cfg); !ok {
98			return room{}, code, errors.New(msg)
99		}
100	
101		s.mu.Lock()
102		defer s.mu.Unlock()
103	
104		records, used, err := s.load()
105		if err != nil {
106			return room{}, http.StatusInternalServerError, err
107		}
108	
109		now := time.Now()
110		newRoom := room{
111			ID:          uniqueRoomID(used),
112			Name:        strings.TrimSpace(cfg.Name),
113			Game:        cfg.Game,
114			Capacity:    cfg.Capacity,
115			TurnSeconds: cfg.TurnSeconds,
116			Status:      "waiting",
117			Visibility:  "public",
118			CreatedAt:   now.UTC().Format(time.RFC3339),
119		}
120	
121		encoded, err := json.Marshal(newRoom)
122		if err != nil {
123			return room{}, http.StatusInternalServerError, fmt.Errorf("序列化房间记录失败: %w", err)
124		}
125		records = append(records, encoded)
126		if err := s.writeAtomic(records); err != nil {
127			return room{}, http.StatusInternalServerError, err
128		}
129		return newRoom, http.StatusCreated, nil
130	}
131	
132	// writeAtomic 先写临时文件再重命名，避免保存失败时破坏原有数据。
133	func (s *roomStore) writeAtomic(records []json.RawMessage) error {
134		payload, err := json.MarshalIndent(records, "", "  ")
135		if err != nil {
136			return fmt.Errorf("序列化房间数据失败: %w", err)
137		}
138		payload = append(payload, '\n')
139	
140		dir := filepath.Dir(s.path)
141		tmp, err := os.CreateTemp(dir, ".rooms-*.tmp")
142		if err != nil {
143			return fmt.Errorf("创建临时数据文件失败: %w", err)
144		}
145		tmpName := tmp.Name()
146		cleanup := func() { _ = os.Remove(tmpName) }
147	
148		if _, err := tmp.Write(payload); err != nil {
149			_ = tmp.Close()
150			cleanup()
151			return fmt.Errorf("写入房间数据失败: %w", err)
152		}
153		if err := tmp.Sync(); err != nil {
154			_ = tmp.Close()
155			cleanup()
156			return fmt.Errorf("同步房间数据失败: %w", err)
157		}
158		if err := tmp.Close(); err != nil {
159			cleanup()
160			return fmt.Errorf("关闭临时数据文件失败: %w", err)
161		}
162		if err := os.Rename(tmpName, s.path); err != nil {
163			cleanup()
164			return fmt.Errorf("保存房间数据失败: %w", err)
165		}
166		return nil
167	}
168	
169	func uniqueRoomID(used map[string]bool) string {
170		var b [16]byte
171		for {
172			if _, err := rand.Read(b[:]); err != nil {
173				panic(fmt.Errorf("生成房间编号失败: %w", err))
174			}
175			id := hex.EncodeToString(b[:])
176			if !used[id] {
177				return id
178			}
179		}
180	}
181	
182	// validateConfig 执行全部字段校验，返回 http 状态码与具体原因。
183	// 所有字段都必须明确提交且合法，不使用任何默认值。
184	func validateConfig(cfg roomConfig) (int, string, bool) {
185		name := strings.TrimSpace(cfg.Name)
186		if name == "" {
187			return http.StatusBadRequest, "房间名称不能为空", false
188		}
189		if len([]rune(name)) > 40 {
190			return http.StatusBadRequest, "房间名称去掉首尾空白后不能超过 40 个字符", false
191		}
192	
193		switch cfg.Game {
194		case "gomoku":
195			if cfg.Capacity != 2 {
196				return http.StatusBadRequest, "五子棋的人数上限固定为 2 人", false
197			}
198		case "ludo":
199			if cfg.Capacity < 2 || cfg.Capacity > 4 {
200				return http.StatusBadRequest, "飞行棋的人数上限必须为 2 至 4 人", false
201			}
202		default:
203			return http.StatusBadRequest, "未知游戏规则，目前仅支持 gomoku（五子棋）和 ludo（飞行棋）", false
204		}
205	
206		if cfg.TurnSeconds != 0 && (cfg.TurnSeconds < 10 || cfg.TurnSeconds > 600) {
207			return http.StatusBadRequest, "每步时间限制只能为 0（不限时）或 10 至 600 秒之间的整数", false
208		}
209		return 0, "", true
210	}
211	
212	func respond(w http.ResponseWriter, status int, value any) {
213		w.Header().Set("Content-Type", "application/json; charset=utf-8")
214		w.WriteHeader(status)
215		_ = json.NewEncoder(w).Encode(value)
216	}
217	
218	func methodNotAllowed(w http.ResponseWriter, allow string) {
219		w.Header().Set("Content-Type", "application/json; charset=utf-8")
220		w.Header().Set("Allow", allow)
221		w.WriteHeader(http.StatusMethodNotAllowed)
222		_ = json.NewEncoder(w).Encode(map[string]string{"error": "method not allowed"})
223	}
224	
225	func run() error {
226		if len(os.Args) < 2 {
227			printHelp()
228			return errors.New("expected serve or --help")
229		}
230		if os.Args[1] == "--help" || os.Args[1] == "-h" {
231			printHelp()
232			return nil
233		}
234		if os.Args[1] != "serve" {
235			return errors.New("expected serve or --help")
236		}
237		args := flag.NewFlagSet("score-arena serve", flag.ContinueOnError)
238		args.SetOutput(os.Stdout)
239		host := args.String("host", "127.0.0.1", "address to bind")
240		port := args.Int("port", 8080, "port to bind; 0 selects an available port")
241		data := args.String("data-dir", "data", "directory for local records")
242		if err := args.Parse(os.Args[2:]); errors.Is(err, flag.ErrHelp) {
243			return nil
244		} else if err != nil {
245			return err
246		}
247		if args.NArg() != 0 {
248			return errors.New("unexpected positional argument")
249		}
250		if *port < 0 || *port > 65535 {
251			return errors.New("port must be between 0 and 65535")
252		}
253		if err := os.MkdirAll(*data, 0700); err != nil {
254			return err
255		}
256		dataFile := filepath.Join(*data, "rooms.json")
257		store := newRoomStore(dataFile)
258	
259		// 首次启动时初始化空数组；已存在则原样保留。
260		file, err := os.OpenFile(dataFile, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
261		if err == nil {
262			_, writeErr := file.WriteString("[]\n")
263			closeErr := file.Close()
264			if writeErr != nil {
265				return writeErr
266			}
267			if closeErr != nil {
268				return closeErr
269			}
270		} else if !errors.Is(err, os.ErrExist) {
271			return err
272		}
273	
274		mux := http.NewServeMux()
275		mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
276			if r.URL.Path != "/" {
277				respond(w, http.StatusNotFound, map[string]string{"error": "not found"})
278				return
279			}
280			if r.Method != http.MethodGet {
281				methodNotAllowed(w, "GET")
282				return
283			}
284			w.Header().Set("Content-Type", "text/html; charset=utf-8")
285			_, _ = w.Write(indexPage)
286		})
287		mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
288			if r.Method != http.MethodGet {
289				methodNotAllowed(w, "GET")
290				return
291			}
292			respond(w, http.StatusOK, map[string]string{"status": "ok", "product": product})
293		})
294		mux.HandleFunc("/api/rooms", func(w http.ResponseWriter, r *http.Request) {
295			switch r.Method {
296			case http.MethodGet:
297				store.mu.Lock()
298				records, _, err := store.load()
299				store.mu.Unlock()
300				if err != nil {
301					respond(w, http.StatusInternalServerError, map[string]string{"error": "无法读取房间数据：" + err.Error()})
302					return
303				}
304				respond(w, http.StatusOK, map[string]any{resourceName: records})
305			case http.MethodPost:
306				handleCreateRoom(w, r, store)
307			default:
308				methodNotAllowed(w, "GET, POST")
309			}
310		})
311	
312		server := &http.Server{
313			Handler:           mux,
314			ReadHeaderTimeout: 5 * time.Second,
315		}
316		listener, err := net.Listen("tcp", net.JoinHostPort(*host, fmt.Sprint(*port)))
317		if err != nil {
318			return err
